459	#[cfg(test)]
460	mod tests {
461	    use super::*;
462	    use callisto_model::PackageId;
463	
464	    fn pkg_id(name: &str) -> PackageId {
465	        PackageId::Bare(name.to_string())
466	    }
467	
468	    fn input(name: &str, dir: &std::path::Path) -> MatrixPackageInput {
469	        MatrixPackageInput {
470	            id: pkg_id(name),
471	            dir_abs: dir.to_path_buf(),
472	            dir_rel: name.to_string(),
473	            name: name.to_string(),
474	        }
475	    }
476	
477	    /// AC-003: no packages declare anything -> the empty-report shape.
478	    #[test]
479	    fn build_matrix_report_empty_workspace_produces_empty_report() {
480	        let report = build_matrix_report(&[]).unwrap();
481	        assert_eq!(report.schema_version, callisto_model::SCHEMA_VERSION);
482	        assert!(report.platform_targets.is_empty());
483	        assert!(report.runtime_versions.is_empty());
484	        assert!(report.diagnostics.is_empty());
485	    }
486	
487	    /// AC-009: platformTargets and runtimeVersions keys are ordered
488	    /// lexicographically by package name across 3+ packages.
489	    #[test]
490	    fn build_matrix_report_orders_packages_lexicographically() {
491	        let tmp = tempfile::tempdir().unwrap();
492	        for name in ["zeta", "alpha", "mid"] {
493	            let dir = tmp.path().join(name);
494	            std::fs::create_dir_all(&dir).unwrap();
495	            std::fs::write(
496	                dir.join("package.json"),
497	                r#"{"napi":{"targets":["aarch64-apple-darwin"]}}"#,
498	            )
499	            .unwrap();
500	        }
501	        let inputs = vec![
502	            input("zeta", &tmp.path().join("zeta")),
503	            input("alpha", &tmp.path().join("alpha")),
504	            input("mid", &tmp.path().join("mid")),
505	        ];
506	        let report = build_matrix_report(&inputs).unwrap();
507	        let keys: Vec<&String> = report.platform_targets.keys().collect();
508	        assert_eq!(keys, vec!["alpha", "mid", "zeta"]);
509	    }
510	
511	    /// AC-005b: a package with both engines.node and requires-python gets a
512	    /// two-element runtimeVersions array, npm before python, and this is not
513	    /// an error.
514	    #[test]
515	    fn build_matrix_report_dual_manifest_runtime_versions_npm_before_python() {
516	        let tmp = tempfile::tempdir().unwrap();
517	        let dir = tmp.path().join("dual-pkg");
518	        std::fs::create_dir_all(&dir).unwrap();
519	        std::fs::write(dir.join("package.json"), r#"{"engines":{"node":">=20.0.0"}}"#).unwrap();
