997	    fn assemble_platform_target_group_empty_array_is_present_not_absent() {
998	        let tmp = tempfile::tempdir().unwrap();
999	        std::fs::write(tmp.path().join("package.json"), r#"{"napi":{"targets":[]}}"#).unwrap();
1000	
1001	        let pkg_json_val = parse_package_json(&tmp.path().join("package.json")).unwrap();
1002	        let pyproject_val = parse_pyproject_toml(&tmp.path().join("pyproject.toml")).unwrap();
1003	
