8	/// Top-level report output from `callisto matrix --format json`.
9	///
10	/// BTreeMap guarantees lexicographic key ordering by registered package name
11	/// (PackageId::name()) without a separate sort step (AC-009).
12	#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
13	#[serde(rename_all = "camelCase")]
14	pub struct MatrixReport {
15	    pub schema_version: u32,
16	    pub platform_targets: BTreeMap<String, PlatformTargetGroup>,
17	    pub runtime_versions: BTreeMap<String, Vec<RuntimeVersionEntry>>,
18	
19	    #[serde(default, skip_serializing_if = "Vec::is_empty")]
20	    pub diagnostics: Vec<Diagnostic>,
21	}
22	
23	impl Report for MatrixReport {
24	    const COMMAND: &'static str = "matrix";
25	
26	    fn schema_version(&self) -> u32 {
27	        self.schema_version
28	    }
29	
